"},"$:/plugins/flibbles/graph/utils/propertyholder.js":{"title":"$:/plugins/flibbles/graph/utils/propertyholder.js","text":"/*\
title: $:/plugins/flibbles/graph/utils/propertyholder.js
type: application/javascript
module-type: graphutils

Class which holds properties, and evaluates their compiled value based on
a supplied set of definitions.

\*/

var Holder = exports.PropertyHolder = {};

var PropertyTypes = $tw.modules.getModulesByTypeAsHashmap("graphpropertytype");

/*
Takes an object of properties and converts them into values ready to be passed
to the engine, using the catalog and this as the context to define them.
*/
Holder.evaluateProperties = function(properties, definitions) {
	var output = Object.create(null);
	// We set the definition and properties to the holder,
	// because some properties may need to evaluate others
	// and the holder will need to remember its rules and properties
	// to do that nested evaluation without passing it around
	this.definitions = definitions;
	this.properties = properties;
	for (var key in this.properties) {
		var value = this.evaluateProperty(key);
		if (value !== null) {
			output[key] = value;
		}
	}
	return output;
};

Holder.evaluateProperty = function(propertyName) {
	var rule = this.definitions[propertyName],
		value = this.properties[propertyName];
	if (rule) {
		if (value === undefined) {
			value = rule.default;
		}
		if (rule && PropertyTypes[rule.type]) {
			 value = PropertyTypes[rule.type].toProperty(rule, value, {wiki: this.wiki, widget: this});
		} else {
			value = value || null;
		}
	}
	return value;
};

/*
Checks if any property in the holder needs to check for refresh, and returns
true if any do need to refresh.
*/
Holder.refreshProperties = function(changedTiddlers) {
	for (var name in this.properties) {
		if (this.refreshProperty(name, changedTiddlers)) {
			return true;
		}
	}
	return false;
};

Holder.refreshProperty = function(propertyName, changedTiddlers) {
	var rule = this.definitions[propertyName];
	if (rule) {
		var type = PropertyTypes[rule.type],
			raw = this.properties[propertyName];
		if (raw === undefined) {
			raw = rule.default;
		}
		if (type
		&& type.refresh
		&& type.refresh(rule, raw, changedTiddlers, this)) {
			return true;
		}
	}
	return false;
};
","type":"application/javascript","module-type":"graphutils"},"$:/plugins/flibbles/graph/utils/widgetiterator.js":{"title":"$:/plugins/flibbles/graph/utils/widgetiterator.js","text":"/*\
title: $:/plugins/flibbles/graph/utils/widgetiterator.js
type: application/javascript
module-type: graphutils

Can be used to iterate through a tree of widgets, given a root.

It goes depth-first, starting the the first leaf widget, and finishes with
the root widget.

\*/

exports.WidgetIterator = function(root) {
	this.stack = [];
	this.ptr = root;
	while (this.ptr.children && this.ptr.children.length > 0) {
		this.stack.push(0);
		this.ptr = this.ptr.children[0];
	}
};

exports.WidgetIterator.prototype.next = function() {
	var rtn, ptr = this.ptr;
	if (!ptr) {
		rtn = {done: true};
	} else {
		rtn = {value: ptr, done: false};
		ptr = ptr.parentWidget;
		var index = this.stack.pop();
		if (index !== undefined) {
			index++;
			if (ptr && ptr.children.length > index) {
				ptr = ptr.children[index];
				this.stack.push(index);
				// Now dive to the lowest child
				while (ptr.children && ptr.children.length > 0) {
					this.stack.push(0);
					ptr = ptr.children[0];
				}
			}
		} else {
			ptr = null;
		}
	}
	this.ptr = ptr;
	return rtn;
};
","type":"application/javascript","module-type":"graphutils"},"$:/plugins/flibbles/graph/utils.js":{"title":"$:/plugins/flibbles/graph/utils.js","text":"/*\
title: $:/plugins/flibbles/graph/utils.js
type: application/javascript
module-type: library

Utility methods used by the graphing widgets.

\*/

"use strict";

var Engines = $tw.modules.createClassesFromModules("graphengine");

$tw.modules.applyMethods("graphutils", exports);

/*
Returns the window for flibbles/graph to use. I do this so that the testing
framework can mock it out on Node.JS.
*/
exports.window = function() { return window; };

exports.getEngineMap = function() {
	return Engines;
};

exports.getEngine = function(name) {
	var engineMap = exports.getEngineMap();
	return engineMap[name] || null;
};

exports.getParentProperties = function(widget, type) {
	// For now, we hard-stop at the graph. We don't take properties outside
	// We may some day, but for now, support for that would be frought with
	// complications
	while (widget.parentWidget && widget.graphObjectType !== "graph") {
		widget = widget.parentWidget;
		if (widget.graphPropertiesWidget && widget.type === type) {
			return widget;
		}
	};
	return null;
};

/*** Destructor methods ***/

// Aren't we all eventually garbage?
var eventualGarbage = [];
var upkeepId;

/*
Register an object for destruction. It's ready to pass on once its
isGarbage method returns true;

object requirements:
.garbageCollect()
.isGarbage() => true/false
*/
exports.registerForGarbageCollection = function(object) {
	var destroy = object.destroy;
	if (destroy) {
		// This object has a destroy method, which means it's probably
		// a widget in ^v5.4.0 TiddlyWiki, which are capable of
		// destruction. We'll use that system instead. It's better.
		object.destroy = function() {
			// Call the widget core destroy method
			destroy.apply(object, arguments);
			// And then our own method
			object.garbageCollect();
		};
	} else {
		// Otherwise, we'll need to keep tabs on this so we can check
		// back in occasionally to see if it should be destroyed.
		if (!upkeepId) {
			upkeepId = setInterval(exports.upkeep, 5000);
		}
		eventualGarbage.push(object);
	}
};

exports.upkeep = function() {
	var i = eventualGarbage.length;
	while (i > 0) {
		i--;
		var object = eventualGarbage[i];
		if (object.isGarbage()) {
			eventualGarbage.splice(i, 1);
			object.garbageCollect();
		}
	}
	// No managed objects. Let's shut down for now.
	if (eventualGarbage.length == 0) {
		clearInterval(upkeepId);
		upkeepId = null;
	}
};
","type":"application/javascript","module-type":"library"},"$:/plugins/flibbles/graph/widgets/action-delay.js":{"text":"/*\

Action widget that introduces a delay before executing any nested actions it contains.

\*/

"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;

var DelayWidget = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
};

DelayWidget.prototype = new Widget();

DelayWidget.prototype.render = function(parent, nextSibling) {
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	this.renderChildren(parent, nextSibling);
};

DelayWidget.prototype.execute = function() {
	this.ms = this.getAttribute("$ms", 0);
	this.state = this.getAttribute("$state");
	this.makeChildWidgets();
};

DelayWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	if ($tw.utils.count(changedAttributes) > 0) {
		this.refreshSelf();
		return true;
	}
	return this.refreshChildren(changedTiddlers);
};

var counter = 0;

DelayWidget.prototype.invokeAction = function(triggeringWidget, event) {
	// The id is used to make sure the later timed invocation corresponds
	// to this method call here.
	var id = (counter++).toString();
	if (this.state) {
		this.wiki.addTiddler({title: this.state, text: id});
	}
	return setTimeout(execute, this.ms, this, triggeringWidget, event, id);
};

DelayWidget.prototype.allowActionPropagation = function() {
	return false;
};

function execute(delayWidget, triggeringWidget, event, id) {
	var state = delayWidget.state;
	if (state) {
		var text = delayWidget.wiki.getTiddlerText(state);
		if (text !== id) {
			// The state tiddler was touched by another action.
			// So we should not act. We're stale.
			return;
		}
	}
	delayWidget.refreshChildren();
	delayWidget.invokeActions(triggeringWidget, event);
	if (state) {
		delayWidget.wiki.deleteTiddler(state);
	}
};

exports["action-delay"] = DelayWidget;
","title":"$:/plugins/flibbles/graph/widgets/action-delay.js","type":"application/javascript","module-type":"widget"},"$:/plugins/flibbles/graph/widgets/action-modal.js":{"text":"/*\

Action widget that creates a modal to select an existing tiddler, or specify a new one. After dialog is confirmed, it will execute any nested actions it contains.

\*/

"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;
var utils = require("../utils.js");

/**
 * This points to whatever action invoked the current modal. It assumes that
 * only one modal is possible at a time. Probably a safe assumption.
 */
var primedWidget;

var ModalWidget = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
};

ModalWidget.prototype = new Widget();

ModalWidget.prototype.render = function(parent, nextSibling) {
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	this.renderChildren(parent, nextSibling);
};

ModalWidget.prototype.execute = function() {
	this.modalTiddler = this.getAttribute("$tiddler");
	this.modal = $tw.modal;
	if (!this.modal || this.modal.wiki !== this.wiki) {
		// Ah, we have a modal working with a subwiki (or a Node.JS system
		// which has no modal). We'll create an overlay of the modal
		// that works with our subwiki instead.
		this.modal = Object.create($tw.modal || null);
		this.modal.wiki = this.wiki;
	}
	this.makeChildWidgets();
};

ModalWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	if ($tw.utils.count(changedAttributes) > 0) {
		this.refreshSelf();
		return true;
	}
	return this.refreshChildren(changedTiddlers);
};

ModalWidget.prototype.invokeAction = function(triggeringWidget, event) {
	if (!$tw.rootWidget.eventListeners['tm-modal-finish']) {
		$tw.rootWidget.addEventListener("tm-modal-finish", function(finishEvent) {
			if (primedWidget) {
				var value = finishEvent.param;
				primedWidget.setVariable("selection", value);
				primedWidget.refreshChildren();
				primedWidget.invokeActions(primedWidget, event);
				primedWidget = undefined;
			}
		});
	}
	primedWidget = this;
	var variables = Object.create(null);
	for (var key in this.attributes) {
		if (key.charAt(0) !== "$") {
			variables[key] = this.attributes[key];
		}
	}
	if (this.modalTiddler) {
		var self = this;
		// We need to delay the assignment of click handlers for a few
		// milliseconds. See Issue #43. If we don't, a click event might
		// follow right after the "make modal" which closes the modal
		// immediately.
		delayEventListenerAssignment(function() {
			self.modal.display(self.modalTiddler, {
				variables: variables,
				event: event});
		});
	}

};

ModalWidget.prototype.allowActionPropagation = function() {
	return false;
};

function delayEventListenerAssignment(method) {
	var assignments = [];
	// We use this requested window instead of just accessing directly
	// so that the test framework can mock it up.
	var window = utils.window();
	var oldListener = window.EventTarget.prototype.addEventListener;
	window.EventTarget.prototype.addEventListener = function(type) {
		var args = Array.prototype.slice.call(arguments);
		if (type === "click") {
			// This is the click which might accidentally apply to the
			// backdrop if we're on mobile. Delay it.
			assignments.push({self: this, args: args});
		} else {
			// Just call through. We don't care about this handler.
			oldListener.apply(this, args);
		}
	};
	try {
		method();
	} finally {
		window.EventTarget.prototype.addEventListener = oldListener;
	}
	setTimeout(function() {
		for (var i = 0; i < assignments.length; i++) {
			var set = assignments[i];
			set.self.addEventListener.apply(set.self, set.args);
		}
	}, 10);
};

exports["action-modal"] = ModalWidget;
","title":"$:/plugins/flibbles/graph/widgets/action-modal.js","type":"application/javascript","module-type":"widget"},"$:/plugins/flibbles/graph/widgets/action-typed.js":{"text":"/*\

Creates two action widgets for adding and removing from typed fields.

\*/

"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;
var typeOperators = $tw.modules.getModulesByTypeAsHashmap("fieldtype");
var relinkPrefix = "$:/config/flibbles/relink/fields/" ;

var TypedWidget = new Widget();

TypedWidget.render = function(parent, nextSibling) {
	this.computeAttributes();
	this.execute();
};

TypedWidget.execute = function() {
	this.actionTiddler = this.getAttribute("$tiddler") || (!this.hasParseTreeNodeAttribute("$tiddler") && this.getVariable("currentTiddler"));
	this.actionField = this.getAttribute("$field");
	this.actionValue = this.getAttribute("$value");
	this.actionTimestamp = this.getAttribute("$timestamp","yes") === "yes";
	this.actionClean = this.getAttribute("$clean","yes") === "yes";
};

TypedWidget.invokeAction = function(triggeringWidget, event) {
	var tiddler = this.wiki.getTiddler(this.actionTiddler),
		hasChanged = false,
		options = {wiki: this.wiki, widget: this};
	if (this.actionTiddler && this.actionField) {
		options.suppressTimestamp = !this.actionTimestamp;
		var typeName = this.wiki.getTiddlerText(relinkPrefix + this.actionField, "list");
		var type = typeOperators[typeName];
		if (type) {
			var newValue = type[this.actionMethod](tiddler, this.actionField, this.actionValue, options);
			if (newValue !== undefined) {
				if (newValue === "" && this.actionClean) {
					newValue = undefined;
				}
				options.wiki.setText(this.actionTiddler, this.actionField, null, newValue, options);
			}
		}
	}
};

$tw.utils.each(["add", "remove"], function(method) {
	var MethodWidget = function(parseTreeNode, options) {
		this.initialise(parseTreeNode, options);
	};

	MethodWidget.prototype = Object.create(TypedWidget);
	MethodWidget.prototype.actionMethod = method;
	exports["action-" + method + "typed"] = MethodWidget;
});
","title":"$:/plugins/flibbles/graph/widgets/action-typed.js","type":"application/javascript","module-type":"widget"},"$:/plugins/flibbles/graph/widgets/action-with.js":{"text":"/*\

Action widget that executes actions within it while exposing variables representing the mouse's current location.

\*/

"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;

var WithWidget = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
};

WithWidget.prototype = new Widget();

WithWidget.prototype.render = function(parent, nextSibling) {
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	this.renderChildren(parent, nextSibling);
};

WithWidget.prototype.execute = function() {
	this.withOffset = this.getAttribute("$offset");
	this.withCanvas = this.getAttribute("$canvas");
	this.makeChildWidgets();
};

WithWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	for (var attribute in changedAttributes) {
		this.refreshSelf();
		return true;
	}
	return this.refreshChildren(changedTiddlers);
};

WithWidget.prototype.invokeAction = function(triggeringWidget, event) {
	var graph = getGraphWidget(this);
	if (graph) {
		if (this.withOffset) {
			var mouse = graph.mouse,
				x = mouse.x.toString(),
				y = mouse.y.toString();
			this.setVariable(this.withOffset + "-x", x);
			this.setVariable(this.withOffset + "-y", y);
		}
		if (this.withCanvas) {
			var element = graph.graphElement;
			this.setVariable(this.withCanvas + "-width", element.offsetWidth);
			this.setVariable(this.withCanvas + "-height", element.offsetHeight);
		}
	}
	this.refreshChildren();
	return true;
};

function getGraphWidget(self) {
	var widget = self.parentWidget;
	while (widget) {
		if (widget.graphObjectType === "graph") {
			return widget;
		}
		widget = widget.parentWidget;
	}
	return null;
};

exports["action-with"] = WithWidget;
","title":"$:/plugins/flibbles/graph/widgets/action-with.js","type":"application/javascript","module-type":"widget"},"$:/plugins/flibbles/graph/widgets/boundingbox.js":{"text":"/*\

Widget for creating a DOM element which has strictly controlled dimensions,
intended for a contained graph.

\*/

"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;
var utils = require("../utils.js");

var BoxWidget = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
	utils.registerForGarbageCollection(this);
	this.resizeInstance = this.resize.bind(this);
	this.window = utils.window();
	this.window.addEventListener("resize", this.resizeInstance);
};

/**
 * Inherit from the base widget class
 */
BoxWidget.prototype = new Widget();

/**
 * Render this widget into the DOM
 */
BoxWidget.prototype.render = function(parent, nextSibling) {
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	this.domNode = this.document.createElement("div");
	this.domNode.className = this.boxClass;
	parent.insertBefore(this.domNode, nextSibling);
	// Make sure this comes AFTER inserting domNode into the tree,
	// otherwise getBoundingClientRect() will be all zeros.
	this.resize();
	this.renderChildren(this.domNode, null);
	this.domNodes.push(this.domNode);
};

/**
 * Compute the internal state of the widget
 */
BoxWidget.prototype.execute = function() {
	this.executeClass();
	this.executeDimensions();
	this.makeChildWidgets();
};

BoxWidget.prototype.executeDimensions = function() {
	var self = this;
	this.widthFilter = this.wiki.compileFilter(this.getAttribute("width", ""));
	this.heightFilter = this.wiki.compileFilter(this.getAttribute("height", ""));
	// We set up the widget so it only gets values for these variables
	// if needed. This keeps down unncessary calls to window and document,
	// and makes the $graph widget usable on Node, if that ever comes up.
	var variableMethods = {
		// It may be better to use document.body.clientWidth,
		// which doesn't consider the scrollbar.
		windowWidth: function() { return self.window.innerWidth.toString(); },
		windowHeight: function() { return self.window.innerHeight.toString(); },
		boundingLeft: function() { return self.domNode.getBoundingClientRect().left.toString(); },
		boundingTop: function() { return self.domNode.getBoundingClientRect().top.toString(); },
	};
	var variables = {};
	for (var name in variableMethods) {
		Object.defineProperty(variables, name, { get: variableMethods[name] });
	}
	this.dimensionWidget = this.makeFakeWidgetWithVariables(variables);
};

/**
 * Selectively refreshes the widget if needed.
 * Returns true if the widget or any of its children needed re-rendering
 */
BoxWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	var changed = false;
	if (changedAttributes["class"]) {
		this.executeClass();
		this.domNode.className = this.boxClass;
		changed = true;
	}
	if ($tw.utils.count(changedAttributes) > 0) {
		this.executeDimensions();
		changed = true;
	}
	// We always try to resize.
	// The $dimension filters might spit out something different.
	this.resize();
	return this.refreshChildren(changedTiddlers) || changed;
};

BoxWidget.prototype.executeClass = function() {
	var nodeClass = "boundingbox";
	var extraClasses = this.getAttribute("class", "");
	if (extraClasses) {
		nodeClass += " " + extraClasses;
	}
	this.boxClass = nodeClass;
};

BoxWidget.prototype.resize = function(event) {
	var newWidth = this.widthFilter(null, this.dimensionWidget)[0] || "";
	var newHeight = this.heightFilter(null, this.dimensionWidget)[0] || "";
	var style = this.domNode.style;
	if (newWidth !== style.width) {
		style.width = newWidth;
	}
	if (newHeight !== style.height) {
		style.height = newHeight;
	}
};

BoxWidget.prototype.garbageCollect = function() {
	this.window.removeEventListener("resize", this.resizeInstance);
};

BoxWidget.prototype.isGarbage = function() {
	var body = this.document.body;
	return !body || !body.contains(this.domNode);
};

exports.boundingbox = BoxWidget;
","title":"$:/plugins/flibbles/graph/widgets/boundingbox.js","type":"application/javascript","module-type":"widget"},"$:/plugins/flibbles/graph/widgets/fieldtranscriber.js":{"text":"/*\

Widget for transcribing the text of one data tiddler
into the field of another. and vice-versa.

\*/

"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;

var Scribers = $tw.modules.getModulesByTypeAsHashmap("fieldtranscribertype");

var ScriberWidget = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
};

ScriberWidget.prototype = new Widget();

ScriberWidget.prototype.render = function(parent, nextSibling) {
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	this.renderChildren(parent, nextSibling);
};

ScriberWidget.prototype.execute = function() {
	this.scribeField = this.getAttribute("field");
	this.scribeTiddler = this.getAttribute("tiddler") || (!this.hasParseTreeNodeAttribute("tiddler") && this.getVariable("currentTiddler"));
	this.scribeType = this.getAttribute("type");
	this.scribeState = this.getAttribute("state");
	if (!this.scribeState) {
		this.scribeState = "$:/temp/flibbles/graph/fieldtranscriber/" + encodeURIComponent(this.scribeField) + "/" + this.scribeTiddler;
	}
	if (!Scribers[this.scribeType]) {
		this.scribeType = "text/plain";
	}
	this.setVariable("state", this.scribeState);
	this.transcriber = Scribers[this.scribeType];
	this.prepState();
	this.makeChildWidgets();
};

ScriberWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	if ($tw.utils.count(changedAttributes) > 0) {
		this.refreshSelf();
		return true;
	}
	if (changedTiddlers[this.scribeState] && this.scribeField) {
		// Our tracked state has changed. Time to transcribe.
		var state = this.wiki.getTiddler(this.scribeState);
		if (state) {
			var stateText = state.getFieldString("text");
			if (this.stateText !== stateText) {
				var fieldText = this.transcriber.toField(stateText);
				if (fieldText !== this.fieldText) {
					this.wiki.setText(this.scribeTiddler, this.scribeField, null, fieldText);
					this.fieldText = fieldText;
					this.stateText = stateText;
				}
			}
		} else {
			this.wiki.setText(this.scribeTiddler, this.scribeField, null, undefined);
			this.fieldText = undefined;
			this.stateText = undefined;
		}
	}
	if (changedTiddlers[this.scribeTiddler]) {
		this.prepState();
	}
	return this.refreshChildren(changedTiddlers);
};

ScriberWidget.prototype.prepState = function() {
	if (this.scribeState && this.scribeField) {
		var tiddler = this.wiki.getTiddler(this.scribeTiddler);
		if (tiddler) {
			var fieldText = tiddler.fields[this.scribeField];
			if (this.fieldText !== fieldText) {
				this.fieldText = fieldText;
				if (fieldText === undefined) {
					this.wiki.deleteTiddler(this.scribeState);
					this.stateText = undefined;
				} else {
					this.stateText = this.transcriber.fromField(fieldText);
					this.wiki.addTiddler({
						title: this.scribeState,
						text: this.stateText,
						type: this.scribeType
					});
				}
			}
		}
	}
};

exports.fieldtranscriber = ScriberWidget;
","title":"$:/plugins/flibbles/graph/widgets/fieldtranscriber.js","type":"application/javascript","module-type":"widget"},"$:/plugins/flibbles/graph/widgets/graphobject.js":{"text":"/*\

Base-class widget that provides standard functionality for all "graph objects",
such as nodes or edges.

\*/

"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;
var utils = require("../utils.js");

var ObjectWidget = function(parseTreeNode, options) {};

ObjectWidget.prototype = new Widget();

// Graph object widgets are a type of property holder.
Object.assign(ObjectWidget.prototype, utils.PropertyHolder);

ObjectWidget.prototype.render = function(parent, nextSibling) {
	this.parentDomNode = parent;
	this.parentPropertiesWidget = utils.getParentProperties(this, this.graphObjectType);
	this.computeAttributes();
	this.execute();
	this.computeParents();
	this.renderChildren(parent, nextSibling);
};

ObjectWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	// Did our parents experience a change to their properties?
	if (this.computeParents()
	// Did our own property attribute change obviously?
	|| $tw.utils.count(changedAttributes) > 0
	// Were the properties cleared because they were stale?
	|| !this.properties
	// maybe properties changed covertly... (expensive)
	|| this.refreshProperties(changedTiddlers)) {
		this.execute();
		// They'll need to be refreshed
		this.properties = null;
	}
	// Then we give our children a chance to refresh too
	return this.refreshChildren(changedTiddlers) || !this.properties;
};

ObjectWidget.prototype.allowActionPropagation = function() {
	return false;
};

/*
Can be overriden to allow object types to set properties based on rules
and behaviors specific to that typeA.
*/
ObjectWidget.prototype.setCustomProperties = function(properties, rules) {};

/*
This is an opportunity for a graphObject to evaluate itself in relation with
all other collected graph objects, as well as knowing its own relative index.
It can use this opportunity to flag itself as needing refreshing, or
return true to indicate it should be pruned away as an illegal object.
*/
ObjectWidget.prototype.curate = function(objects, index) { return false; };

/*
Calculates and stores the properties raw values in the object.
Then returns the evaluated property values to be used by the engine.
*/
ObjectWidget.prototype.calculatePropertyValues = function(rules) {
	return this.evaluateProperties(this.computeProperties(rules), rules);
};

/*
Computes the properties for this object and returns them in an object.
*/
ObjectWidget.prototype.computeProperties = function(rules) {
	var newProperties = Object.create(null);
	// First, we set any auto-properties, so that anything else
	// will have the opportunity to override them.
	for (var name in rules) {
		var property = rules[name];
		// It's flagged to always be sent to the engine.
		// Send along the default value. It may be overridden momentarily.
		if (property.always) {
			newProperties[name] = property.default;
		}
	}
	// Then we travel down and set properties based on containing
	// $property widgets.
	for (var i = this.applicableParents.length-1; i >= 0; i--) {
		var widget = this.applicableParents[i];
		for (var property in widget.properties) {
			newProperties[property] = widget.properties[property];
		}
	}
	// Then object types get a chance to set properties based on
	// their own unique rules.
	this.setCustomProperties(newProperties, rules);
	// Then we set properties based on explicit attributes
	// on this object. These take highest priority.
	for (var key in this.attributes) {
		if (key.charAt(0) !== "$") {
			var value = this.attributes[key];
			if (value) {
				newProperties[key] = this.attributes[key];
			}
		}
	}
	return newProperties;
};

ObjectWidget.prototype.catchGraphEvent = function(graphEvent, triggeringWidget, variables) {
	var actions = this.attributes[graphEvent.type];
	if (actions) {
		triggeringWidget.invokeActionString(actions, triggeringWidget, graphEvent.event, variables);
		return true;
	}
	return false;
};

ObjectWidget.prototype.computeParents = function() {
	var index = 0;
	var changed = false;
	var list = this.applicableParents = this.applicableParents || [];
	this.traversePropertyWidgets(function(widget) {
		if (list[index] !== widget) {
			list[index] = widget;
			changed = true;
		} else if (widget.propertiesChanged) {
			changed = true;
		}
		index++;
	});
	if (index !== list.length) {
		list.length = index;
		changed = true;
	}
	return changed;
};

/**
 * Explore for any $properties which might apply to this. Can be overridden.
 */
ObjectWidget.prototype.traversePropertyWidgets = function(method) {
	var widget = this.parentPropertiesWidget;
	while (widget !== null) {
		if (widget.filterFunc([this.id], widget).length > 0) {
			method(widget);
		}
		widget = widget.parentPropertiesWidget;
	}
};

exports.graphobject = ObjectWidget;
","title":"$:/plugins/flibbles/graph/widgets/graphobject.js","type":"application/javascript","module-type":"widget"},"$:/plugins/flibbles/graph/widgets/messagerelay.js":{"text":"/*\

Widget for relaying emitted messages to other parts of the widget.
This allows buttons for a graph to exist outside of that graph.

\*/

"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;
var utils = require("../utils.js");

// Relayed is used to avoid infinite loops. Once an event is relayed,
// it puts itself in this object under the relay name, so it can't be
// relayed again through that name
var relayed = Object.create(null);

var RelayWidget = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
	utils.registerForGarbageCollection(this);
};

RelayWidget.prototype = new Widget();

RelayWidget.prototype.render = function(parent, nextSibling) {
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	this.renderChildren(parent, nextSibling);
};

RelayWidget.prototype.execute = function() {
	this.relayName = this.getAttribute("name");
	this.relayTo = this.getAttribute("to");
	if (this.relayName) {
		var register = this.wiki.relayRegister = this.wiki.relayRegister || Object.create(null);
		register[this.relayName] = register[this.relayName] || [];
		register[this.relayName].push(this);
	}
	this.makeChildWidgets();
};

RelayWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	var changed = false;
	if (changedAttributes.name) {
		this.garbageCollect();
		this.refreshSelf();
		return true;
	}
	if (changedAttributes.to) {
		this.relayTo = this.getAttribute("to");
		changed = true;
	}
	return this.refreshChildren(changedTiddlers) || changed;
};

RelayWidget.prototype.dispatchEvent = function(event) {
	var register = this.wiki.relayRegister;
	if (this.relayTo
	&& register
	&& register[this.relayTo]
	&& relayed[this.relayTo] !== event) {
		relayed[this.relayTo] = event;
		var targets = register[this.relayTo];
		for (var i = 0; i < targets.length; i++) {
			var target = targets[i];
			if (!target.isGarbage()) {
				targets[i].dispatchEvent(event);
			}
		}
	} else {
		return Widget.prototype.dispatchEvent.call(this, event);
	}
};

RelayWidget.prototype.isGarbage = function() {
	var root = rootWidget(this);
	return root !== $tw.rootWidget;
};

RelayWidget.prototype.garbageCollect = function() {
	if (this.relayName) {
		var register = this.wiki.relayRegister[this.relayName];
		for (var i = 0; i < register.length; i++) {
			if (register[i] === this) {
				// Remove this from the register
				register.splice(i, 1);
			}
		}
		this.relayName = undefined;
	}
};

function rootWidget(relay) {
	var parent = relay.parentWidget;
	while (parent) {
		var i = 0;
		for (; i < parent.children.length; i++) {
			if (parent.children[i] === relay) {
				// Confirmed that the parent still owns this child
				break;
			}
		}
		if (i == parent.children.length) {
			// Ownership was not confirmed
			return null;
		}
		relay = parent;
		parent = relay.parentWidget;
	}
	return relay;
};

exports.messagerelay = RelayWidget;
","title":"$:/plugins/flibbles/graph/widgets/messagerelay.js","type":"application/javascript","module-type":"widget"},"$:/plugins/flibbles/graph/widgets/properties.js":{"text":"/*\

Widget for setting properties on graph objects.

\*/

"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;
var utils = require("../utils.js");
var Engines = $tw.modules.getModulesByTypeAsHashmap("graphengine");
var PropertyTypes = $tw.modules.getModulesByTypeAsHashmap("graphpropertytype");

var Properties = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
};

Properties.prototype = new Widget();

Properties.prototype.graphPropertiesWidget = true;

Properties.prototype.render = function(parent, nextSibling) {
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	this.renderChildren(parent, nextSibling);
};

Properties.prototype.execute = function() {
	this.type = this.getAttribute("$for", "nodes");
	this.parentPropertiesWidget = utils.getParentProperties(this, this.type);
	this.filter = this.getAttribute("$filter");
	this.properties = this.getProperties();
	this.filterFunc = this.filter? this.wiki.compileFilter(this.filter): function(source) { return source; };
	this.makeChildWidgets();
};

Properties.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	this.propertiesChanged = false;
	if (changedAttributes["$for"]) {
		// If the $for changed, we need to refocus to the different object type.
		this.refreshSelf();
		return true;
	}
	if (propertiesChanged(changedAttributes)
	|| changedAttributes["$tiddler"]
	|| changedAttributes["$field"]
	|| (this.dataTiddler
		&& changedTiddlers[this.dataTiddler]
		&& this.rawData !== getTiddlerString(this.wiki, this.dataTiddler, this.field))) {
		// Our styling attributes have changed, so everything this $style
		// affects needs to refresh.
		this.properties = this.getProperties();
		this.propertiesChanged = true;
	}
	// If we have a filterFunc, we need to worry about whether this style
	// applies to a different subset of its children objects or not.
	if (changedAttributes["$filter"]) {
		this.filter = this.getAttribute("$filter");
		this.filterFunc = this.filter? this.wiki.compileFilter(this.filter): function(source) { return source; };
	}
	return this.refreshChildren(changedTiddlers) || this.propertiesChanged;
};

Properties.prototype.getProperties = function() {
	this.field = this.getAttribute("$field");
	this.dataTiddler = this.getAttribute("$tiddler");
	if (!this.dataTiddler && this.field) {
		this.dataTiddler = this.getVariable("currentTiddler");
	}
	var styleObject = Object.create(null);
	if (this.dataTiddler) {
		var data;
		// We recall the actual raw data string so
		// we can see whether it changes later on.
		this.rawData = getTiddlerString(this.wiki, this.dataTiddler, this.field);
		if (!this.field || this.field === "text") {
			data = this.wiki.getTiddlerData(this.dataTiddler);
		} else {
			try {
				data = this.rawData? JSON.parse(this.rawData): {};
			} catch {
				data = {};
			}
		}
		for (var entry in data) {
			var datum = data[entry];
			// We only accept non-empty values
			if (datum && typeof datum === "string") {
				styleObject[entry] = datum;
			}
		}
	}
	for (var name in this.attributes) {
		if (name.charAt(0) !== '$' && this.attributes[name]) {
			styleObject[name] = this.attributes[name];
		}
	}
	return styleObject;
};

function getTiddlerString(wiki, title, field) {
	var tiddler = wiki.getTiddler(title);
	return tiddler && tiddler.getFieldString(field || "text");
};

Properties.prototype.catchGraphEvent = function(graphEvent, target, variables) {
	if (graphEvent.objectType === this.type
	&& this.filterFunc([target.id], this).length > 0) {
		var actions = this.properties[graphEvent.type];
		if (actions) {
			variables.targetTiddler = graphEvent.id;
			this.invokeActionString(actions, this, graphEvent.event, variables);
			return true;
		}
	}
	return false;
};

function propertiesChanged(changedAttributes) {
	for (var name in changedAttributes) {
		if (name.charAt(0) !== "$") {
			return true;
		}
	}
	return false;
};

exports.properties = Properties;
","title":"$:/plugins/flibbles/graph/widgets/properties.js","type":"application/javascript","module-type":"widget"},"$:/plugins/flibbles/graph/widgets/subclass/edge.js":{"text":"/*\

Widget for creating edges within graphs.

\*/

"use strict";

var nextId = 1;

exports.baseClass = "graphobject";
exports.name = "edge";
// These are object properties that will get added to the variable context
// when action strings are invoked.
exports.actionContext = ["id", "fromTiddler", "toTiddler"];

exports.constructor = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
};

var EdgeWidget = exports.prototype = {};

EdgeWidget.graphObjectType = "edges";

EdgeWidget.execute = function() {
	this.id = this.getAttribute("$id");
	if (!this.id) {
		// We do this instead of using getAttribute's default arg
		// so we don't increment unecessarily, and maybe reuse
		// the same auto-id if this edge refreshes Self. This'll give better
		// results when updating the graph. It's a CHANGED edge, not a new one.
		this.counter = this.counter || nextId++;
		this.id = "$:/edge/" + this.counter;
	}
	this.fromTiddler = this.getAttribute("$from", this.getVariable("currentTiddler"));
	this.toTiddler = this.getAttribute("$to", this.getVariable("toTiddler"));
	this.makeChildWidgets();
};

EdgeWidget.setCustomProperties = function(properties) {
	if (this.fromTiddler) {
		properties.from = this.fromTiddler;
	}
	if (this.toTiddler) {
		properties.to = this.toTiddler;
	}
};

EdgeWidget.curate = function(objects) {
	// Edges are not legal if there aren't corresponding nodes for its
	// to and from.
	return !objects.nodes
	|| !objects.nodes[this.fromTiddler]
	|| !objects.nodes[this.toTiddler];
};
","title":"$:/plugins/flibbles/graph/widgets/subclass/edge.js","type":"application/javascript","module-type":"widget-subclass"},"$:/plugins/flibbles/graph/widgets/subclass/edit-color.js":{"text":"/*\

Specialized form of <$edit-text/> which handles displaying palette colors,
if that's what its underlying value specifies.

\*/

exports.baseClass = "edit-text";
exports.name = "edit-color";

var ColorType = require("../../propertytypes/color.js");

exports.constructor = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
};

var EditWidget = exports.prototype = {};

/*
We expand on getEditInfo to evaluate any potential palette colors and adust
the info accordingly.
*/
EditWidget.getEditInfo = function() {
	var info = Object.getPrototypeOf(Object.getPrototypeOf(this)).getEditInfo.call(this);
	this._rawColor = info.value;
	if (info.value) {
		info.value = ColorType.toProperty(null, info.value, {widget: this}) || info.value;
	}
	return info;
};

/*
We hard-code this widget to be a color input.
*/
EditWidget.execute = function() {
	Object.getPrototypeOf(Object.getPrototypeOf(this)).execute.call(this);
	this.editType = "color";
	this.editTag = "input";
};

/*
We elaborate refresh to also check if the palette has changed.
*/
EditWidget.refresh = function(changedTiddlers) {
	if (Object.getPrototypeOf(Object.getPrototypeOf(this)).refresh.call(this, changedTiddlers)) {
		return true;
	}
	if (ColorType.refresh(null, this._rawColor, changedTiddlers, this)) {
		var editInfo = this.getEditInfo();
		this.updateEditor(editInfo.value, editInfo.type);
	}
};
","title":"$:/plugins/flibbles/graph/widgets/subclass/edit-color.js","type":"application/javascript","module-type":"widget-subclass"},"$:/plugins/flibbles/graph/widgets/subclass/graph.js":{"text":"/*\

Widget for creating graphs.

\*/

"use strict";

var utils = require("../../utils.js");

// Let's collect all the possible graph object types. We might need to
// reference their base classes later.
var GraphObjectTypes = {};
$tw.modules.forEachModuleOfType("widget-subclass", function(title, module) {
	if (module.baseClass == "graphobject") {
		module.graphObjectType = module.prototype.graphObjectType;
		GraphObjectTypes[module.graphObjectType] = module;
	}
});

exports.baseClass = "graphobject";
exports.name = "graph";

exports.constructor = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
	utils.registerForGarbageCollection(this);
	this.window = utils.window();
};

/*
Inherit from the base widget class
*/
var GraphWidget = exports.prototype = {};

GraphWidget.graphObjectType = "graph";

/*
Render this widget into the DOM
*/
GraphWidget.render = function(parent, nextSibling) {
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	this.graphElement = this.document.createElement("div");
	var className = "graph-canvas";
	if (!this.graphEngine) {
		className += " graph-error";
	} else {
		className += " graph-engine-" + this.graphEngineName.toLowerCase();
	}
	this.graphElement.className = className;
	this.graphElement.addEventListener("mousemove", this);
	this.domNodes.push(this.graphElement);
	parent.insertBefore(this.graphElement, nextSibling);
	this.renderChildren(this.graphElement, null);

	this.computeParents();
	// Render and recenter the view
	if(this.graphEngine) {
		this.graphEngine.onevent = GraphWidget.handleGraphEvent.bind(this);
		var objects = this.computeGraphObjects() || {};
		objects.graph = this.calculatePropertyValues(getCatalog(this.graphEngine, "graph"));
		try {
			this.graphEngine.init(this.graphElement, objects, {wiki: this.wiki, widget: this});
		} catch(e) {
			// Technically, we should drop this engine without destroying it.
			// It didn't successfully init, so it's not initialized.
			// This means it's up to the engines to be "Strong Exception Safe".
			this.graphEngine = undefined;
			// Something went wrong. Rebuild this widget as an error displayer
			console.error(e);
			this.errorState = e.message || e.toString();
			this.refreshSelf();
		}
	}
};

/*
Compute the internal state of the widget
*/
GraphWidget.execute = function() {
	this.graphEngineName = this.getEngineName();
	this.setVariable("graphengine", this.graphEngineName);
	this.mouse = {x: "0", y: "0"};
	var Engine = utils.getEngine(this.graphEngineName);
	if (!Engine || this.errorState) {
		var message;
		if (this.errorState) {
			message = this.errorState;
			this.errorState = null;
		} else if (!this.graphEngineName) {
			message = "No graphing libraries installed.";
		} else if (this.getAttribute("$engine")) {
			message = "'" + this.graphEngineName + "' graphing library not found.";
		} else {
			message = "Graph plugin configured to use missing '" + this.graphEngineName + "' engine. Fix this in plugin settings.";
		}
		this.makeChildWidgets([{type: "element", tag: "span", children: [{type: "text", text: message}]}]);
		this.graphEngine = undefined;
	} else {
		this.graphObjects = null;
		this.makeChildWidgets();
		this.graphEngine = new Engine(this.wiki);
	}
};

/*
Selectively refreshes the widget if needed. Returns true if the widget or any of its children needed re-rendering
*/
GraphWidget.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes(),
		newName = this.getEngineName();
	if(changedAttributes["$engine"] || (this.graphEngineName !== newName)) {
		this.refreshSelf();
		return true;
	}
	var selfChanged = false, childrenChanged = false;
	var objects;
	for (var attribute in changedAttributes) {
		if (attribute.charAt(0) !== "$") {
			selfChanged = true;
			break;
		}
	}
	if (this.refreshChildren(changedTiddlers)) {
		childrenChanged = true;
	}
	if (!this.graphEngine && (selfChanged || childrenChanged)) {
		// At this point, we know widgets have literally changed.
		// If we're in an error state, we can refresh self now, because
		// all properties would have to be regenerated anyway.
		this.refreshSelf();
		return true;
	}
	// From here on, we now try to narrow down which properties changed,
	// because we can update instead of full refresh. Updates only bother
	// with changed properties.
	if (childrenChanged) {
		// Children have changed. Look for changed nodes and edges
		// and evaluate their properties
		objects = this.computeGraphObjects();
	}
	selfChanged = this.computeParents() || selfChanged;
	if (selfChanged || this.refreshProperties(changedTiddlers)) {
		var rules = getCatalog(this.graphEngine, "graph");
		var newTypecastProperties = this.calculatePropertyValues(rules);
		objects = objects || {};
		objects.graph = newTypecastProperties;
	}
	if (objects) {
		try {
			this.graphEngine.update(objects);
		} catch (e) {
			// Something went wrong. Rebuild this widget as an error displayer
			console.error(e);
			this.errorState = e.message || e.toString();
			this.refreshSelf();
		}
	}
	return selfChanged || childrenChanged;
};

GraphWidget.refreshSelf = function() {
	var nextSibling = this.findNextSiblingDomNode();
	this.removeChildDomNodes();
	if (this.graphEngine) {
		this.graphEngine.destroy();
	}
	this.render(this.parentDomNode, nextSibling);
};

GraphWidget.garbageCollect = function() {
	if (this.graphEngine) {
		this.graphEngine.destroy();
	}
};

GraphWidget.isGarbage = function() {
	var body = this.document.body;
	return !body || !body.contains(this.graphElement);
};

GraphWidget.getEngineName = function() {
	return this.getAttribute("$engine") || this.getVariable("graphengine");
};

/**
 * This overrides a graphobject method so we're looking inward instead of
 * upward for properties that apply to this widget.
 */
GraphWidget.traversePropertyWidgets = function(method) {
	var iterator = new utils.WidgetIterator(this);
	var ptr = null;
	var results;
	while (!(results = iterator.next()).done) {
		var widget = results.value;
		if (widget.type === "graph") {
			// We make a quick in place linked list
			results.next = ptr;
			ptr = results;
		}
	}
	// Now we run through that list. This way, we apply the found properties
	// in reverse, since the first found should be executed last as having
	// lowest priority.
	while (ptr !== null) {
		method(ptr.value);
		ptr = ptr.next;
	}
};

/**
 * This handles messages bubbling up from internal graph widgets
 */
GraphWidget.dispatchEvent = function(event) {
	var messageDef = this.graphEngine.messages && this.graphEngine.messages[event.type];
	if (messageDef) {
		// We create a propertyHolder out of the widget.
		var message = Object.assign(Object.create(event.widget), utils.PropertyHolder);
		var params = message.evaluateProperties(event.paramObject, messageDef);
		if (this.graphEngine.handleMessage(event, params) === false) {
			return false;
		}
	}
	if (this.parentWidget) {
		return this.parentWidget.dispatchEvent(event);
	}
};

GraphWidget.handleGraphEvent = function(graphEvent, variables) {
	if (graphEvent.objectType === "graph") {
		var iterator = new utils.WidgetIterator(this);
		var results;
		while (!(results = iterator.next()).done) {
			var widget = results.value;
			if (widget.type === "graph") {
				var actions = widget.properties[graphEvent.type];
				if (actions) {
					widget.invokeActionString(actions, widget, graphEvent.event, variables);
				}
			}
		}
		this.catchGraphEvent(graphEvent, this, variables);
	} else {
		var category = this.graphObjects[graphEvent.objectType];
		var object = category && category[graphEvent.id];
		if (object) {
			variables = variables || {};
			// We let the graph object assign some state,such as the id of the
			// targeted node, or the nodes of the targeted edge.
			var module = GraphObjectTypes[object.graphObjectType];
			if (module) {
				$tw.utils.each(module.actionContext, function(name) {
					variables[name] = object[name];
				});
			}
			// Make sure it's an objects we actually know about
			var target = object;
			while (object && object !== this) {
				if (object.catchGraphEvent) {
					// Start at the object. Go up, finding $style to handle this
					object.catchGraphEvent(graphEvent, target, variables);
				}
				object = object.parentWidget;
			}
		}
	}
};

GraphWidget.handleEvent = function(event) {
	// Must be a mousemove, because that's the only one we signed up for.
	// All we do is remember the mouse position if we need it later for
	// graph events.
	this.mouse.x = event.offsetX;
	this.mouse.y = event.offsetY;
};

GraphWidget.computeGraphObjects = function() {
	var prevObjects = this.graphObjects || {},
		widgetInfo = findGraphObjects(this),
		newObjects = widgetInfo.objects,
		order = widgetInfo.order;
	// Prune any objects which shouldn't be passed along
	curateObjects(newObjects, order, this.graphEngine.properties);
	var evaluated =  getDifferences(this.graphEngine, prevObjects, newObjects);
	this.graphObjects = newObjects;
	return evaluated;
};

function getCatalog(graphEngine, type) {
	var definitions = graphEngine.properties;
	return (definitions && definitions[type]) || Object.create(null);
};

function findGraphObjects(graphWidget) {
	var newObjects = {};
	var discoveryOrder = {};
	var iterator = new utils.WidgetIterator(graphWidget),
		results;
	while (!(results = iterator.next()).done) {
		var widget = results.value;
		var type = widget.graphObjectType;
		if (type && type !== "graph") {
			newObjects[type] = newObjects[type] || Object.create(null);
			newObjects[type][widget.id] = widget;
			// We've got to recall the order that we found the widgets in
			// storing them in objects doesn't work, because that sorts oddly
			discoveryOrder[type] = discoveryOrder[type] || new $tw.utils.LinkedList();
			discoveryOrder[type].pushTop(widget.id);
		}
	}
	for (var type in discoveryOrder) {
		discoveryOrder[type] = discoveryOrder[type].toArray();
	}
	return {objects: newObjects, order: discoveryOrder};
};

/**
 * Checking for objects that should be pruned must take place after all
 * objects have been collected. Some object types, like edge, need to know
 * what other objects are present to know if they're valid or not.
 */
function curateObjects(objects, orders, catalog) {
	for (var groupName in objects) {
		var type = GraphObjectTypes[groupName];
		if (type && type.graphObjectType !== "graph") {
			var group = objects[groupName];
			var order = orders[groupName];
			var rules = catalog[type.graphObjectType];
			var index = 0;
			for (var i = 0; i < order.length; i++) {
				var id = order[i];
				if (group[id].curate(objects, rules, index)) {
					group[id] = undefined;
				} else {
					++index;
				}
			}
		}
	}
};

function getDifferences(graphEngine, prevObjects, newObjects) {
	var objects = null
	for (var type in prevObjects) {
		var was = prevObjects[type];
		var is = newObjects[type];
		var catalog = getCatalog(graphEngine, type);
		for (var id in was) {
			if (was[id]) {
				if (!is || !is[id]) {
					// It Was, and no longer Is. Flag for deletion
					objects = objects || {};
					objects[type] = objects[type] || Object.create(null);
					objects[type][id] = null;
				} else if (!is[id].properties || is[id] !== was[id]) {
					// It changed, or is another instance of the same ID.
					// Updated it.
					objects = objects || {};
					objects[type] = objects[type] || Object.create(null);
					objects[type][id] = is[id].calculatePropertyValues(catalog);
				}
			}
		}
	}
	for (var type in newObjects) {
		var was = prevObjects? prevObjects[type]: undefined;
		var is = newObjects[type];
		var catalog = getCatalog(graphEngine, type);
		for (var id in is) {
			if (is[id] && (!was || !was[id])) {
				// It has been added. Add it.
				objects = objects || {};
				objects[type] = objects[type] || Object.create(null);
				objects[type][id] = is[id].calculatePropertyValues(catalog);
			}
		}
	}
	return objects;
};
","title":"$:/plugins/flibbles/graph/widgets/subclass/graph.js","type":"application/javascript","module-type":"widget-subclass"},"$:/plugins/flibbles/graph/widgets/subclass/node.js":{"text":"/*\

Widget for creating nodes within graphs.

\*/

"use strict";

var axes = ['x', 'y', 'z', 'w'];

exports.baseClass = "graphobject";
exports.name = "node";
// These are object properties that will get added to the variable context
// when action strings are invoked.
exports.actionContext = ["nodeTiddler"];

exports.constructor = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
};

var NodeWidget = exports.prototype = {};

NodeWidget.graphObjectType = "nodes";

NodeWidget.execute = function() {
	this.id = this.getAttribute("$tiddler", this.getVariable("currentTiddler"));
	// We set this for the actionContext, which gets automatically scraped
	// when actions for this object get executed.
	this.nodeTiddler = this.id;
	this.pos = this.getAttribute("$pos");
	this.makeChildWidgets();
};

NodeWidget.curate = function(objects, rules, index) {
	if (rules.index && this.index !== index) {
		this.index = index;
		this.properties = null;
	}
	// Nodes must have non-empty IDs. If empty, this node should be pruned.
	return !this.id;
};

NodeWidget.setCustomProperties = function(properties, rules) {
	if (this.pos) {
		var points = this.pos.split(",");
		var count = Math.min(points.length, axes.length);
		for (var i = 0; i < count; i++) {
			if (points[i]) {
				properties[axes[i]] = points[i];
			}
		}
	}
	if (this.index !== undefined) {
		properties.index = this.index;
	}
};
","title":"$:/plugins/flibbles/graph/widgets/subclass/node.js","type":"application/javascript","module-type":"widget-subclass"},"$:/plugins/flibbles/graph/widgets/fieldtranscriber/filter.js":{"text":"/*\

Type for transcribing application/x-tiddler-filter between text and field.

Changes \n into "  " between runs to mitigate the need for multilines.
However, it's impossible to guarantee a single line filter if newlines are
used in operands.

\*/

"use strict";

exports.name = "application/x-tiddler-filter";

exports.toField = function(text) {
	return filterWhitespaceWalk(text, function(start, end) {
		var substr = text.substring(start, end);
		var change = substr.replaceAll("\n", "  ");
		return substr !== change ? change: null;
	}).trim();
};

exports.fromField = function(text) {
	return filterWhitespaceWalk(text, function(start, end) {
		var substr = text.substring(start, end);
		var change = substr.replaceAll("  ", "\n");
		return substr !== change ? change: null;
	});
};

var brackets = { "{": "}", "[": "]", "<": ">" };

function filterWhitespaceWalk(filterString, method) {
	var p = 0, replaceHead = 0, replacements = [], match, nextBracketPos;
	var whitespaceRegExp = /(\s+)/mg;
	var operandRegExp = /((?:\+|\-|~|=|\:(\w+)(?:\:([\w\:, ]*))?)?)(?:(\[)|(?:"([^"]*)")|(?:'([^']*)')|([^\s\[\]]+))/mg;
	while (p < filterString.length) {
		whitespaceRegExp.lastIndex = p;
		match = whitespaceRegExp.exec(filterString);
		if (match && match.index === p) {
			var end = p + match[0].length;
			var replacement = method(p, end);
			if (replacement !== null) {
				replacements.push(filterString.substring(replaceHead, p));
				replacements.push(replacement);
				replaceHead = end;
			}
			p = end;
		}
		if (p < filterString.length) {
			operandRegExp.lastIndex = p;
			match = operandRegExp.exec(filterString);
			if (!match || match.index !== p) {
				// Broken filter
				return filterString;
			}
			if (match[1]) {
				// Skip the named prefix
				p += match[1].length;
			}
			if (match[4]) {
				// It's a filter operation. Skip by [...]
				if (filterString.charAt(p++) !== "[") {
					return filterString;
				}
				do {
					if(filterString.charAt(p) === "!") {
						filterString.charAt(p++);
					}
					// Get the operator name
					nextBracketPos = filterString.substring(p).search(/[\[\{<\/]/);
					if(nextBracketPos === -1) {
						return filterString;
					}
					nextBracketPos += p;
					var bracket = filterString.charAt(nextBracketPos);
					nextBracketPos = filterString.indexOf(brackets[bracket], p);
					if (nextBracketPos === -1) {
						return filterString;
					}
					p = nextBracketPos + 1;
				} while (filterString.charAt(p++) !== "]");
			} else {
				p = match.index + match[0].length;
			}
		}
	}
	if (replacements.length > 0) {
		replacements.push(filterString.substr(replaceHead));
		return replacements.join("");
	}
	return filterString;
};
","title":"$:/plugins/flibbles/graph/widgets/fieldtranscriber/filter.js","type":"application/javascript","module-type":"fieldtranscribertype"},"$:/plugins/flibbles/graph/widgets/fieldtranscriber/json.js":{"text":"/*\

Type for transcribing application/json between text and field.

Focuses on keeping dataTiddler style pretty printing for text, but puts all
json on one line for fields.

\*/

"use strict";

exports.name = "application/json";

exports.toField = function(text) {
	if (!text) {
		return "";
	}
	try {
		return JSON.stringify(JSON.parse(text));
	} catch {
		return "{}";
	}
};

exports.fromField = function(text) {
	if (!text) {
		return "";
	}
	try {
		return JSON.stringify(JSON.parse(text), null, $tw.config.preferences.jsonSpaces);
	} catch {
		return "{}";
	}
};
